#import "../Registry/TFAIToolRegistry.h"
#import "TFAIBuildQueue.h"
#import "../../Studio.h"
extern BOOL TMCBuildIsRunning(void);
#import "../Background/TFAIBackground.h"
#import "../Background/TFAINotifications.h"
#import "../LiveActivity/TFAILiveActivity.h"
#import "../UI/TFAIUIHelpers.h"
#import "../Providers/TFAIProtocol.h"
#include "TFAIBuildQueueCore.inc"
@interface TFAIBuildTasks : UITableViewController
@property NSTimer *timer;
@property NSArray *rows;
@property BOOL swiping;
@property BOOL selecting;
@property NSMutableSet<NSString *> *selected;
@end
@implementation TFAIBuildTasks
- (void)viewDidLoad{[super viewDidLoad];self.title=@"构建任务队列";self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=82;self.selected=[NSMutableSet set];[self installNormalBarItems];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];if(self.selecting){self.selecting=NO;[self.selected removeAllObjects];[self installNormalBarItems];}[self reload];__weak typeof(self) weak=self;self.timer=[NSTimer scheduledTimerWithTimeInterval:1 repeats:YES block:^(NSTimer *t){[weak reload];}];}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];[self.timer invalidate];self.timer=nil;self.navigationController.toolbarHidden=YES;}
- (void)installNormalBarItems{__weak typeof(self) weak=self;UIBarButtonItem *select=[[UIBarButtonItem alloc]initWithTitle:@"选择" style:UIBarButtonItemStylePlain target:self action:@selector(toggleSelection)];UIAction *clear=[UIAction actionWithTitle:@"清空全部任务" image:[UIImage systemImageNamed:@"trash"] identifier:nil handler:^(UIAction *a){[weak confirmClearAll];}];clear.attributes=UIMenuElementAttributesDestructive;UIBarButtonItem *more=[[UIBarButtonItem alloc]initWithImage:[UIImage systemImageNamed:@"ellipsis.circle"] menu:[UIMenu menuWithTitle:@"" children:@[clear]]];self.navigationItem.rightBarButtonItems=@[select,more];self.navigationItem.leftBarButtonItem=nil;self.navigationController.toolbarHidden=YES;self.toolbarItems=nil;}
- (void)installSelectionBarItems{self.navigationItem.rightBarButtonItems=@[[[UIBarButtonItem alloc]initWithTitle:@"取消" style:UIBarButtonItemStylePlain target:self action:@selector(toggleSelection)]];UIBarButtonItem *all=[[UIBarButtonItem alloc]initWithTitle:@"全选" style:UIBarButtonItemStylePlain target:self action:@selector(selectAllRows)];all.enabled=self.rows.count>0;self.navigationItem.leftBarButtonItem=all;self.navigationController.toolbarHidden=NO;[self updateSelectionToolbar];}
- (void)updateSelectionToolbar{UIBarButtonItem *space=[[UIBarButtonItem alloc]initWithBarButtonSystemItem:UIBarButtonSystemItemFlexibleSpace target:nil action:nil];UIBarButtonItem *remove=[[UIBarButtonItem alloc]initWithTitle:[NSString stringWithFormat:@"删除（%lu）",(unsigned long)self.selected.count] style:UIBarButtonItemStylePlain target:self action:@selector(deleteSelectedRows)];remove.tintColor=UIColor.systemRedColor;remove.enabled=self.selected.count>0;self.toolbarItems=@[space,remove];}
- (void)toggleSelection{self.selecting=!self.selecting;[self.selected removeAllObjects];if(self.selecting)[self installSelectionBarItems];else[self installNormalBarItems];[self.tableView reloadData];}
- (void)selectAllRows{[self.selected removeAllObjects];for(NSDictionary *j in self.rows)if(j[@"id"])[self.selected addObject:j[@"id"]];[self.tableView reloadData];[self updateSelectionToolbar];}
- (void)deleteSelectedRows{NSArray *rows=[self.rows filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary *j,NSDictionary *bindings){return [self.selected containsObject:j[@"id"]];}]];if(!rows.count)return;UIAlertController *a=[UIAlertController alertControllerWithTitle:@"删除所选任务？" message:[NSString stringWithFormat:@"共 %lu 个任务。运行中的任务会被取消，已完成的任务会从队列移除。",(unsigned long)rows.count] preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];__weak typeof(self) weak=self;[a addAction:[UIAlertAction actionWithTitle:@"删除" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[weak removeOrCancelRows:rows];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)confirmClearAll{if(!self.rows.count)return;UIAlertController *a=[UIAlertController alertControllerWithTitle:@"清空构建队列？" message:[NSString stringWithFormat:@"共 %lu 个任务。运行中的任务会被取消，已完成的任务会从队列移除。",(unsigned long)self.rows.count] preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];__weak typeof(self) weak=self;[a addAction:[UIAlertAction actionWithTitle:@"清空" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[weak removeOrCancelRows:weak.rows];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)removeOrCancelRows:(NSArray *)rows{for(NSDictionary *j in rows){BOOL busy=[@[@"running",@"queued",@"cancelling"] containsObject:j[@"state"]];if(busy)[TFAIBuildQueue.shared cancel:j[@"id"]];else[TFAIBuildQueue.shared remove:j[@"id"]];}[self.selected removeAllObjects];if(self.selecting){self.selecting=NO;[self installNormalBarItems];}[self reload];}
- (void)reload{self.rows=[TFAIBuildQueue.shared.tasks reverseObjectEnumerator].allObjects;if(self.swiping)return;[self.tableView reloadData];}
- (void)tableView:(UITableView *)t willBeginEditingRowAtIndexPath:(NSIndexPath *)i{self.swiping=YES;}
- (void)tableView:(UITableView *)t didEndEditingRowAtIndexPath:(NSIndexPath *)i{self.swiping=NO;[self reload];}
- (NSArray<UIContextualAction *> *)queueActionsForRow:(NSIndexPath *)i{NSDictionary *j=self.rows[i.row];BOOL busy=[@[@"running",@"queued",@"cancelling"] containsObject:j[@"state"]];UIContextualAction *action=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleDestructive title:busy?@"取消":@"删除" handler:^(UIContextualAction *a,UIView *v,void(^done)(BOOL)){if(busy)[TFAIBuildQueue.shared cancel:j[@"id"]];else if(![TFAIBuildQueue.shared remove:j[@"id"]]){done(NO);return;}[self reload];done(YES);dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(0.4*NSEC_PER_SEC)),dispatch_get_main_queue(),^{[self reload];});}];action.backgroundColor=busy?UIColor.systemOrangeColor:UIColor.systemRedColor;return @[action];}
- (UISwipeActionsConfiguration *)tableView:(UITableView *)t trailingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath *)i{return [UISwipeActionsConfiguration configurationWithActions:[self queueActionsForRow:i]];}
- (UISwipeActionsConfiguration *)tableView:(UITableView *)t leadingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath *)i{return [UISwipeActionsConfiguration configurationWithActions:[self queueActionsForRow:i]];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.rows.count;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return @"同一时间运行一个本机构建。取消在快照或编译步骤边界生效。失败与中断保留日志、产物路径和检查点；重新构建核对当前文件并沿用现有审批。后台运行仍受iOS系统调度。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *j=self.rows[i.row];UITableViewCell *c=AICell(j[@"name"],[NSString stringWithFormat:@"%@ · %.0f%%\n%@",j[@"state"],[j[@"progress"] doubleValue]*100,j[@"stage"]],@"hammer");if(self.selecting){c.selectionStyle=UITableViewCellSelectionStyleDefault;c.accessoryType=[self.selected containsObject:j[@"id"]]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;}return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{if(self.selecting){[t deselectRowAtIndexPath:i animated:YES];NSDictionary *j=self.rows[i.row];if(j[@"id"]){if([self.selected containsObject:j[@"id"]])[self.selected removeObject:j[@"id"]];else[self.selected addObject:j[@"id"]];}[t reloadRowsAtIndexPaths:@[i] withRowAnimation:UITableViewRowAnimationNone];[self updateSelectionToolbar];return;}NSDictionary *j=self.rows[i.row];UIAlertController *a=[UIAlertController alertControllerWithTitle:j[@"name"] message:j[@"stage"] preferredStyle:UIAlertControllerStyleActionSheet];if([@[@"running",@"queued"] containsObject:j[@"state"]])[a addAction:[UIAlertAction actionWithTitle:@"取消任务" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[TFAIBuildQueue.shared cancel:j[@"id"]];[self reload];}]];if([@[@"failed",@"interrupted",@"cancelled"] containsObject:j[@"state"]])[a addAction:[UIAlertAction actionWithTitle:@"从检查点重新构建…" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIAlertController *confirm=[UIAlertController alertControllerWithTitle:@"重新构建当前项目？" message:@"这是一次新的本机构建。将重新核对当前源码、配置与SDK；只有校验一致的成功编译步骤可复用，失败步骤重跑。" preferredStyle:UIAlertControllerStyleAlert];[confirm addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[confirm addAction:[UIAlertAction actionWithTitle:@"确认构建" style:UIAlertActionStyleDefault handler:^(UIAlertAction *y){if(!TMCStudioResumeBuild(j[@"root"],self.navigationController))AIAlert(self,@"项目已移动或删除",@"请从项目列表打开可用项目后重新构建。");}]];[self presentViewController:confirm animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"查看检查点 / 结果" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIViewController *page=[UIViewController new];page.title=@"任务记录";UITextView *v=[[UITextView alloc]initWithFrame:page.view.bounds];v.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;v.editable=NO;v.font=[UIFont monospacedSystemFontOfSize:12 weight:UIFontWeightRegular];v.text=[[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:j options:NSJSONWritingPrettyPrinted error:nil] encoding:NSUTF8StringEncoding];[page.view addSubview:v];[self.navigationController pushViewController:page animated:YES];}]];[a addAction:[UIAlertAction actionWithTitle:@"关闭" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:a animated:YES completion:nil];}
@end
UIViewController *TFAIBuildQueueController(void){return [[TFAIBuildTasks alloc]initWithStyle:UITableViewStyleInsetGrouped];}
